//! The FLOWS panel over the core socket (F-SPLIT-03, D-S5-01, D-S5-02): the six job traits of `iyakki-agent-api::flows_jobs` are generated by
//! `dist/split/gen_rpc.py`; `dist/split/gen_flows_jobs.py` composes the UI's six remote objects as one `FlowsJobs` and writes the core's guard. This
//! file holds the entry (`flows_jobs`), the scope each call needs and the sentence for a call that is refused.
//!
//! The rules, all of them fail closed:
//! * the person is read again: the policy comes from the core's accounts by the name in the call, never from the UI, and a `by` the UI claims is
//!   replaced by the account's own name in the core ([`GuardedFlowsJobs`]);
//! * every call names a scope the socket must hold: `flows:read` to look, `flows:run` to start, stop and decide a run, `flows:edit` to change flows,
//!   the assistant's book and the message policy, `flows:hooks` for webhooks and for letting a program run (the asks). A method this table does
//!   not name needs a scope nobody holds;
//! * a hook's shared secret does not cross (D-SPLIT-03-SECRETS): the wire form of `Created` drops it.

use std::sync::Arc;

use iyakki_agent_api::{FlowsAssist, FlowsChannel, FlowsDrafts, FlowsHooks, FlowsJobs, FlowsMeta, FlowsRuns};
use iyakki_ui_client::facets::{FLOWS_EDIT, FLOWS_HOOKS};
use serde_json::{json, Value};

use crate::gen_flows_jobs::{GuardedFlowsJobs, RemoteFlowsJobs};
use crate::gen_remote::{RemoteFlowsAssist, RemoteFlowsChannel, RemoteFlowsDrafts, RemoteFlowsHooks, RemoteFlowsMeta, RemoteFlowsRuns};
use crate::served::{ServedParts, NOT_SERVED};
use crate::{de, ser, Obj, Registry, RemoteServicesHandle, ServicesRoot};

const READ: &str = "flows:read";
const RUN: &str = "flows:run";
/// A scope nobody holds: what a method this table does not name needs.
const NONE: &str = "flows:unknown-call";

/// The scope the call `iface::method` needs, when it is a FLOWS call (`None`: not one, the table has no say).
pub(crate) fn flows_scope(iface: &str, method: &str) -> Option<&'static str> {
    Some(match (iface, method) {
        ("ServicesHandle", "flows_jobs") => READ,
        ("FlowsMeta", "user" | "policy" | "data" | "dir" | "svc_dir" | "who" | "flow_names" | "vision_line") => READ,
        ("FlowsMeta", "audit" | "set_last_flow" | "chat_handle" | "refresh_model_lists") => FLOWS_EDIT,
        ("FlowsDrafts", "summaries" | "issues" | "get_draft" | "published" | "versions" | "get_version" | "meta_of" | "draft_stamp" | "export_json") => READ,
        ("FlowsDrafts", "rollback" | "publish" | "save_edit" | "create_draft" | "import_json" | "from_template" | "drop_version" | "delete_flow") => FLOWS_EDIT,
        ("FlowsDrafts", "allow_program") => FLOWS_HOOKS,
        ("FlowsRuns", "get_run" | "run_summaries" | "run_counts" | "revision" | "ticking" | "next_runs" | "browser_session") => READ,
        ("FlowsRuns", "start_run" | "decide" | "card_decide" | "cancel" | "retry_node" | "skip_node" | "rerun_from" | "node_updates" | "apply_node_update" | "test_node" | "report_run" | "withdraw_permissions") => RUN,
        ("FlowsAssist", "assist_global" | "assist_book" | "assist_open_list" | "assist_now" | "assist_watch" | "assist_paused" | "assist_readout") => READ,
        ("FlowsAssist", "assist_set_enabled" | "assist_set_global_cap" | "assist_set_matrix" | "assist_set_profile" | "assist_set_watch" | "assist_set_status" | "assist_set_paused" | "assist_adopt" | "assist_reject" | "trial_whole" | "assist_after_publish") => FLOWS_EDIT,
        ("FlowsHooks", "hook_views") => READ,
        ("FlowsHooks", "hook_create" | "hook_regenerate" | "hook_enable" | "hook_disable" | "hook_public") => FLOWS_HOOKS,
        ("FlowsChannel", "chan_allowed" | "msg_policy_get" | "msg_held" | "msg_watching") => READ,
        ("FlowsChannel", "chan_set" | "msg_policy_set" | "msg_ack") => FLOWS_EDIT,
        ("FlowsMeta" | "FlowsDrafts" | "FlowsRuns" | "FlowsAssist" | "FlowsHooks" | "FlowsChannel", _) => NONE,
        _ => return None,
    })
}

/// The sentence for a call the socket's scopes do not allow.
pub(crate) fn refused(iface: &str, method: &str, scope: &str) -> String {
    format!("{NOT_SERVED}: {iface}::{method} needs the scope {scope}, which this socket does not hold")
}

/// The core's end of `flows_jobs(user, policy)`: the account's own policy is read from the core's accounts (the one the UI sent is ignored), the six
/// objects are made over the guard and their ids answered; `null` when the core has no flows environment for that account.
pub(crate) fn serve_flows(root: &ServicesRoot, reg: &Registry<'_>, method: &str, a: Value) -> Option<Result<Value, String>> {
    if method != "flows_jobs" {
        return None;
    }
    Some((|| {
        let (user, _claimed): (String, Value) = de(a)?;
        let accounts = ServedParts::need(&root.parts.accounts, "accounts")?;
        let policy = accounts.get_public(&user).ok_or_else(|| format!("{NOT_SERVED}: no account {user}"))?.policy();
        let Some(jobs) = root.svc.flows_jobs(&user, &policy) else { return Ok(Value::Null) };
        let g = Arc::new(GuardedFlowsJobs(jobs));
        ser(&[
            reg.add(Obj::FlowsMeta(g.clone() as Arc<dyn FlowsMeta>)),
            reg.add(Obj::FlowsDrafts(g.clone() as Arc<dyn FlowsDrafts>)),
            reg.add(Obj::FlowsRuns(g.clone() as Arc<dyn FlowsRuns>)),
            reg.add(Obj::FlowsAssist(g.clone() as Arc<dyn FlowsAssist>)),
            reg.add(Obj::FlowsHooks(g.clone() as Arc<dyn FlowsHooks>)),
            reg.add(Obj::FlowsChannel(g as Arc<dyn FlowsChannel>)),
        ])
    })())
}

impl RemoteServicesHandle {
    /// The account's flows environment: six remote objects as one `FlowsJobs`. `None` when the core has none for the account (or the socket may not
    /// look at flows).
    pub(crate) fn m_flows_jobs(&self, user: &str, policy: &iyakki_sec::policy::Policy) -> Option<Arc<dyn FlowsJobs>> {
        let ids: Option<[u64; 6]> = self.rpc.call::<Option<[u64; 6]>>("ServicesHandle", 0, "flows_jobs", json!([user, policy])).ok().flatten();
        let [meta, drafts, runs, assist, hooks, channel] = ids?;
        let rpc = &self.rpc;
        Some(Arc::new(RemoteFlowsJobs {
            meta: RemoteFlowsMeta::new(rpc.clone(), meta),
            drafts: RemoteFlowsDrafts::new(rpc.clone(), drafts),
            runs: RemoteFlowsRuns::new(rpc.clone(), runs),
            assist: RemoteFlowsAssist::new(rpc.clone(), assist),
            hooks: RemoteFlowsHooks::new(rpc.clone(), hooks),
            channel: RemoteFlowsChannel::new(rpc.clone(), channel),
        }))
    }
}
